mapper.select:
SELECT COUNT(1) FROM (
    SELECT A.MSG_ID, A.SENDER_ID, A.RECEIVER_PHONE, A.MSG_TYPE, A.SEND_STATUS, A.SEND_DT 
    FROM TB_SMS_HISTORY A 
    WHERE 1=1 

          AND A.SEND_DT BETWEEN #{startDate} AND #{endDate} 


          AND A.RECEIVER_PHONE LIKE '%' || #{receiverNo} || '%' 


          AND A.MSG_TYPE = #{sendType}

) A

SELECT * FROM (
    SELECT A.*, ROWNUM AS RNUM FROM (
        SELECT X.* FROM (
            SELECT A.MSG_ID, A.SENDER_ID, A.RECEIVER_PHONE, A.MSG_TYPE, A.SEND_STATUS, A.SEND_DT 
            FROM TB_SMS_HISTORY A 
            WHERE 1=1 

                  AND A.SEND_DT BETWEEN #{startDate} AND #{endDate} 


                  AND A.RECEIVER_PHONE LIKE '%' || #{receiverNo} || '%' 


                  AND A.MSG_TYPE = #{sendType}

        ) X

    ) A WHERE ROWNUM <= #{offset} + #{size}
) WHERE RNUM > #{offset}
